import { test, expect } from '@playwright/test';

test('rejects invalid quantity and completes a valid checkout', async ({ page }) => {
  await page.goto('/app/checkout.html');
  const quantity = page.getByLabel('Quantity');
  const placeOrder = page.getByRole('button', { name: 'Place order' });

  await quantity.fill('0');
  await placeOrder.click();
  await expect(page.getByRole('alert')).toHaveText('Quantity must be at least 1');

  await quantity.fill('2');
  await placeOrder.click();
  const confirmation = page.getByRole('status');
  await expect(confirmation).toBeVisible();
  await expect(confirmation).toContainText('2 items');
});
